// Copies the compiled ABI into frontend/abi.js. Run after changing the contract:
//   npm run compile && npm run abi
const fs = require("fs");
const path = require("path");

const artifact = path.join(
  __dirname,
  "../artifacts/contracts/CrowdfundingMilestone.sol/CrowdfundingMilestone.json"
);
const { abi } = JSON.parse(fs.readFileSync(artifact, "utf8"));
const output = path.join(__dirname, "../frontend/abi.js");

fs.writeFileSync(
  output,
  "// Generated by scripts/export-abi.js. Do not edit by hand.\n" +
    `export const CONTRACT_ABI = ${JSON.stringify(abi, null, 2)};\n`
);
console.log(`Wrote ${abi.length} ABI entries to ${path.relative(process.cwd(), output)}`);
